'use strict';

// MODULES //

var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var isIntegerArray = require( '@stdlib/assert/is-integer-array' );
var getShape = require( '@stdlib/ndarray/shape' );
var emptyLike = require( '@stdlib/ndarray/empty-like' );
var normalizeIndex = require( '@stdlib/ndarray/base/normalize-index' );
var assign = require( '@stdlib/ndarray/base/assign' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns an ndarray with element at specified indices replaced by a provided value.
*
* @param {ndarray} x - input ndarray
* @param {IntegerArray} indices - indices of the element to replace
* @param {*} value - value to set
* @throws {TypeError} First argument must be an ndarray
* @throws {TypeError} Second argument must be an array of integers
* @throws {RangeError} Third argument must be an array of valid indices
* @returns {ndarray} output ndarray
*
* @example
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* var buffer = [ 1, 2, 3, 4 ];
* var shape = [ 2, 2 ];
* var order = 'row-major';
* var strides = [ 2, 1 ];
* var offset = 0;
*
* var x = ndarray( 'generic', buffer, shape, strides, offset, order  );
*
* var out = ndarrayWith( x, [ 0, 0 ], 5 );
* // returns <ndarray>
*
* var v = out.get( 0, 0 );
* // returns 5
*/
function ndarrayWith( x, indices, value ) {
	var args;
	var out;
	var idx;
	var sh;
	var i;

	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray. Value: `%s`.', x ) );
	}
	if ( !isIntegerArray( indices ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an array of integers. Value: `%s`.', indices ) );
	}
	// Copy the input array:
	sh = getShape( x );
	out = emptyLike( x );
	assign( [ x, out ] );

	// Resolve the provided indices:
	args = [];
	for ( i = 0; i < sh.length; i++ ) {
		idx = normalizeIndex( indices[ i ], sh[ i ] );
		if ( idx === -1 ) {
			throw new RangeError( format( 'invalid argument. Second argument must be an array of valid indices. Value: %s`.`', indices ) );
		}
		args.push( idx );
	}
	args.push( value );

	// Set the element at the specified indices:
	out.set.apply( out, args );
	return out;
}


// EXPORTS //

module.exports = ndarrayWith;
